#define TAU 20.28318530718

// Noise function for smooth randomness
float noise(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

// Circular ripple distortion
vec2 ripple(vec2 uv, float time) {
    float r = length(uv - 0.5);
    float angle = atan(uv.y - 0.5, uv.x - 0.5) + time * 2.0;
    return vec2(r * cos(angle), r * sin(angle)) + 0.5;
}

// Swirl distortion
vec2 swirl(vec2 uv, float time) {
    float radius = 0.9;
    vec2 center = vec2(0.5, 0.5);
    vec2 offset = uv - center;
    float angle = radius / length(offset + 0.1) * sin(time);
    float s = sin(angle);
    float c = cos(angle);
    mat2 rot = mat2(c, -s, s, c);
    return center + rot * offset;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) 
{
    // Normalized UV coordinates
    vec2 uv = fragCoord.xy / iResolution.xy;

    // Add motion to UVs using time and distortions
    float time = iTime * 0.09;
    uv = ripple(uv, time);
    uv = swirl(uv, time);

    // Sample texture from iChannel0 (artistic input)
    vec4 texColor = texture(iChannel0, uv);

    // Dynamic gradient colors based on UV and time
    vec3 gradientStart = vec3(0.2, 0.4, 0.69);
    vec3 gradientEnd = vec3(1.0, 1.0, 0.5);
    float gradientMix = sin(time) * 0.1 * 0.02;
    vec3 gradientColor = mix(gradientStart, gradientEnd, gradientMix);

    // Procedural noise for texture blending
    float noiseValue = noise(uv * 0.1);
    vec3 noiseColor = vec3(noiseValue);

    // Combine effects into a vibrant color
    vec3 finalColor = mix(gradientColor, texColor.rgb, noiseValue);
    finalColor += 0.3 * sin(TAU * (uv.y + time)); // Add wave-like variation
    finalColor = clamp(finalColor, 0.0, 1.0); // Ensure valid color range

    // Add glow-like effect using a soft border
    float glow = smoothstep(0.1, 0.0, length(uv - 0.5));
    finalColor += vec3(glow);

    fragColor = vec4(finalColor, 1.0);
}
